"""One source for the step-by-step workbook and Russian Markdown guide."""
from network_test_basics import BASICS, REPORTS, SOLO

PREPARATION = [
    ['P1','Распаковать комплект', 'Каждый участник: ПКМ по ZIP комплекта → «Извлечь всё» → выберите папку вне Skyrim, например D:\\SkyCraftTest. Затем откройте полученную папку. Все названные здесь CMD находятся в её корне; запускайте их двойным щелчком из Проводника. Не запускайте CMD прямо внутри ZIP.', 'В папке есть НАЧАТЬ.txt, tools, docs, JAR и package-manifest.json. При проверке одному читайте «Без друга» B0–B11. Подробное объяснение путей и ввода — G1–G8.'],
    ['P2','Обновить Java-мод', 'Каждый участник: закройте обе игры по G2. Если network.3 уже установлен, этот шаг пропустите. Если исходный SkyCraft 0.1.2 работает, запустите «Установить обновление.cmd» из P1; в ответ на запрос вставьте полный путь папки Minecraft из G1. Дождитесь сообщения об успешной установке. Если исходного SkyCraft ещё нет, сначала выполните docs/YS-FRIEND.md из комплекта.', 'Старые SkyCraft/e4mc сохранятся в SkyCraft-YS-backups рядом с экземпляром. Настройки и миры сохраняются. Единственный активный JAR SkyCraft имеет версию 0.1.2-ys.network.3; e4mc отсутствует, Fabric API остаётся. Проверка версии и SHA256 — P3.'],
    ['P3','Проверить версии', 'Каждый участник: запустите «Проверить сборку.cmd» из P1. Каталог Minecraft — G1; каталог Skyrim — папка с SkyrimSE.exe; каталог модов — MO2 → Настройки → Пути → Моды (Mods). Дождитесь пути отчёта, откройте ПРОВЕРКА.txt в созданной папке reports.\nВ Prism: ПКМ по экземпляру → Редактировать → Версии: Minecraft 26.3, Loader 0.19.5, Fabric API 0.161.0+26.3. Java 25 проверяется в настройках Java экземпляра. В MO2 слева галочками включите SkyCraft и Address Library.', 'Проверенный Skyrim runtime 1.7.104.0, SKSE 2.3.1, соответствующая Address Library. installation.json/ПРОВЕРКА.txt показывают факты и хеши. Каждый FAIL сначала разберите по его тексту; WARN прочитайте и проверьте вручную. Наличие файлов не подтверждает галочки MO2 и успешный запуск.'],
    ['P4','Проверить одиночный запуск', 'Каждый участник выполняет G5: SKSE через MO2 → меню → отдельное тестовое сохранение после Хелгена → HUD Minecraft, WASD, камера. До изменений мира выполните копирование G3. Для двух ПК выберите одну и ту же локацию Skyrim, например одну точку на дороге у Ривервуда; запишите название и ориентир, используйте одинаковые моды, изменяющие эту локацию.', 'Оба отдельно видят HUD и управляют игроком. При отсутствии HUD/ввода — отчёт R1. Не перезаписывайте основное сохранение. Мир Minecraft находится в MINECRAFT\\saves\\SkyCraft независимо от выбранного сохранения Skyrim.'],
    ['P5','Найти чат', 'На загруженном сохранении нажмите T в окне Skyrim: исходный SkyCraft передаёт чат Minecraft и текстовый ввод через свой мост. Наберите /skycraft debug status и Enter. Escape закрывает чат. Набирайте команды латиницей; переключите раскладку на английскую. Отдельное окно Minecraft не требуется.', 'В чате ответ SkyCraft, а не «Unknown command». Если T не открыл чат, запишите это как отдельный сбой ввода; не продолжайте команды вслепую.'],
    ['P6','Создать исходные условия', 'На каждом ПК: закройте обе игры по G2 → сохраните копии G3 → откройте MINECRAFT\\config\\skycraft.properties → примените пять строк G4, включая join= и network.mode=DIRECT → Ctrl+S → запустите снова по G5.\nВ своих VPN/Cloudflare/zapret запишите состояние до теста, затем выключите подключение/обработку через интерфейс каждой программы на время базовой проверки. Если у программы нет понятного выключателя, оставьте её состояние как unknown и запишите это; не завершайте неизвестные службы.', 'Теперь ясно, какой файл изменён, и значения сохранены. Если нельзя отключить один из инструментов, базовую проверку обозначьте PARTIAL с фактическими условиями. После успешного L01/I01 проверяйте инструменты по отдельным сценариям. Для одного ПК используйте B0–B11.'],
    ['P7','Назначить роли и ID', 'Для двух ПК договоритесь: host владеет миром Minecraft и выполняет /skycraft host; client подключается командой /join. LAN: L01_01, разные сети IPv4: I01_01. Для новой попытки замените _01 на _02 во всех командах и мастерах обоих ПК.\nОткройте docs\\testing\\SkyCraft-Network-Tests.xlsx из P1, сохраните рабочую копию. В «Сценарии подробно» фильтром ID выберите сценарий; в «Условия прогонов» найдите строку того же Run ID. Правила заполнения — R6.', 'ID без пробелов/кириллицы, до 64 символов: латинские буквы, цифры, _ и -. На обоих ПК один ID, роли разные. Для одного ПК готовые ID/роли даны в B1–B9.'],
]

ADDRESSES = [
    ['A0','Выбрать ветку', 'Если оба ПК подключены к одному домашнему роутеру обычным Ethernet/Wi-Fi — A1–A3 (LAN). Если в разных квартирах/сетях — A4–A7 (Интернет IPv4) либо A8–A9 (IPv6). Доступ к одному VPN-провайдеру не делает ПК общей LAN. 127.0.0.1 — только текущий ПК.', 'Назначьте переменные на бумаге: HOST_LAN_IP, HOST_ROUTER, HOST_WAN_IP, HOST_PORT=25565, EXTERNAL_PORT=25565, ENDPOINT. Это подписи, не текст для вставки в команду.'],
    ['A1','Найти LAN IPv4 хоста', 'На хосте, не на клиенте: «Адреса хоста.cmd» либо PowerShell: Get-NetIPConfiguration. Найдите подключённый Ethernet/Wi-Fi, к которому относятся оба ПК. Запишите IPv4Address и IPv4DefaultGateway.NextHop. Не выбирайте loopback, 169.254.*, WARP/VPN/виртуальный адаптер вместо вашей физической LAN.', 'HOST_LAN_IP = IPv4Address физического адаптера. HOST_ROUTER = его IPv4DefaultGateway.NextHop. Например 192.168.1.20 и 192.168.1.1; это примеры, берите свои значения.'],
    ['A2','Передать LAN адрес', 'После /skycraft host 25565 хост передаёт другу HOST_LAN_IP:25565 текстом. Если IPv4 хоста реально 192.168.1.20, готовая строка 192.168.1.20:25565. Клиент использует адрес ХОСТА, не свой IPv4 и не шлюз роутера.', 'ENDPOINT = HOST_LAN_IP:HOST_PORT. Для LAN проброс порта на роутере не нужен. Гостевой Wi-Fi с изоляцией клиентов может запретить соединение.'],
    ['A3','Проверить LAN порт', 'После открытия мира клиент в PowerShell: Test-NetConnection -ComputerName HOST_LAN_IP -Port 25565 -InformationLevel Detailed. Подставьте свой адрес без :порт в ComputerName. Например: Test-NetConnection -ComputerName 192.168.1.20 -Port 25565. Смотрите TcpTestSucceeded, RemoteAddress, InterfaceAlias. Затем проверьте тот же адрес через /skycraft netcheck ENDPOINT в чате игры.', 'True/успех netcheck = TCP открыт. False: проверить, что хост не вышел из мира, порт 25565 слушается, выбрана правильная LAN, нет гостевой изоляции и разрешён входящий TCP. PingSucceeded отдельно успех не доказывает.'],
    ['A4','Найти WAN IPv4 в другой сети', 'Хост сначала выполняет A1.\n1. Откройте браузер. В адресную строку введите http:// и свой HOST_ROUTER: например http://192.168.1.1, если шлюз именно такой. Если страница не открылась — адрес/HTTPS берётся из руководства вашего роутера.\n2. Войдите паролем администратора роутера (это может отличаться от пароля Wi-Fi).\n3. Откройте Internet/WAN/Статус подключения к провайдеру. Перепишите поле IPv4 адрес WAN и время; это HOST_WAN_IP. Названия меню зависят от модели, ищите состояние внешнего подключения, а не LAN. Если доступа к роутеру нет — внешний IPv4 тест пока BLOCKED.', 'Не копируйте выходной IP включённого VPN с сайта «мой IP». WAN 10.*, 192.168.*, 172.16.*–172.31.* или 100.64.*–100.127.* означает ещё один NAT; дальше A5. Если WAN изменится, старое приглашение перестанет подходить. Пароль роутера в отчёт не включается.'],
    ['A5','Проверить NAT и выбрать хоста', 'Если WAN частный: выясните, чей вышестоящий роутер. Для двух собственных роутеров TCP-порт надо направить на каждом; при CGNAT провайдера нужен доступный публичный адрес от провайдера либо глобальный IPv6. Если публичный вход есть только у друга, поменяйте host/client. Если нет у обоих — I01=BLOCKED; сохраняйте факт, не ставьте FAIL моду.', 'Собственного ретранслятора/автоматического NAT traversal в этой сборке ещё нет. Клиентский SOCKS/HTTP-прокси не открывает входящий порт хоста. Отсутствие публичного входа конфигом не исправляется.'],
    ['A6','Направить TCP-порт на ПК хоста', 'На своём роутере A4:\n1. Откройте DHCP/список устройств. Найдите ПК хоста по HOST_LAN_IP из A1. Для него включите резервирование адреса (Address reservation/статическая аренда). MAC при необходимости берётся из этого устройства либо PowerShell: Get-NetAdapter | Select-Object Name,MacAddress,Status — тот же Ethernet/Wi-Fi A1.\n2. В Port forwarding/Virtual server/Переадресация портов нажмите «Добавить»: имя SkyCraft; протокол TCP; внешний порт 25565; внутренний IP HOST_LAN_IP; внутренний порт 25565; правило включено. Сохраните/Примените.\n3. Выполните F1 на Windows хоста. G5 запускает игру; в чате /skycraft host 25565.\n4. Из WAN поля A4 и внешнего порта правила составьте ENDPOINT, передайте его клиенту текстом.', 'Пример: WAN 203.0.113.10 и внешний порт 30000 дают строку 203.0.113.10:30000; этот IP документационный, замените своим WAN. При внутреннем 25565 команда хоста остаётся /skycraft host 25565. Для двух собственных роутеров также A10. Если меню непонятно, остановитесь и укажите модель/непройденный шаг; не создавайте правило наугад.'],
    ['A7','Проверить Интернет с клиента', 'Клиент из другой сети: Test-NetConnection -ComputerName HOST_WAN_IP -Port EXTERNAL_PORT -InformationLevel Detailed. Затем /skycraft netcheck ENDPOINT выбранным игровым транспортом. Проверка своего WAN адреса с ПК хоста зависит от NAT loopback и не заменяет проверку друга. При VPN на хосте входящая доступность и обратный маршрут могут измениться — H01/H02 проверяют это заново.', 'ENDPOINT = WAN IPv4 хоста + внешний порт. True/TCP успех — можно идти к /join. Если timeout: WAN/NAT, проброс, Windows firewall, правила роутера, VPN хоста и фильтрация.'],
    ['A8','Найти глобальный IPv6', 'На хосте: Get-NetIPAddress -AddressFamily IPv6 | Select-Object InterfaceAlias,IPAddress,AddressState. Нужен Preferred глобальный адрес подключённого адаптера с реальным IPv6 от провайдера. Не передавайте ::1, fe80:: (link-local), fc*/fd* (локальные ULA), 2001:db8:: (пример документации). Если выбор непонятен, пришлите результат и не угадывайте.', 'IPv6 ENDPOINT = [IPv6_ХОСТА]:25565, со скобками. В PowerShell ComputerName адрес без скобок и без :порт. Нужен рабочий IPv6 на обоих ПК.'],
    ['A9','Проверить IPv6 снаружи', 'Откройте мир на хосте. Для IPv6 обычно не нужна трансляция IPv4-порта; в IPv6 firewall роутера и Windows хоста разрешите входящий TCP 25565 к выбранному IPv6. Клиент: Test-NetConnection -ComputerName IPv6_ХОСТА -Port 25565. Затем /skycraft netcheck [IPv6_ХОСТА]:25565 и /join [IPv6_ХОСТА]:25565. После смены адреса IPv6 получите его заново.', 'Успех TCP с клиента подтверждает доступ к порту. IPv6 от VPN не считать доступным входящим адресом без этой проверки.'],
    ['A10','Два собственных роутера', 'Только если оба роутера ваши и доступны: ПК хоста подключён к внутреннему роутеру, его WAN подключён к внешнему роутеру.\n1. На внутреннем роутере A6 направляет TCP 25565 на HOST_LAN_IP.\n2. Перепишите WAN IPv4 внутреннего роутера со страницы A4. Например 192.168.0.2.\n3. На внешнем роутере закрепите этот адрес за внутренним роутером; создайте TCP правило: внешний 25565 → IP 192.168.0.2, внутренний порт 25565. IP примера замените действительным WAN внутреннего роутера.\n4. Клиент получает публичный WAN именно внешнего роутера:25565; проверяет его по A7.', 'Если вышестоящий NAT принадлежит провайдеру, правило на чужом роутере создать нельзя: запросите у провайдера публичный входящий IPv4 либо проверяйте глобальный IPv6 A8–A9. Без доступного адреса I01=BLOCKED, причину внесите в таблицу.'],
    ['F1','Правило Windows firewall', 'На хосте Win+R → wf.msc → Правила для входящих подключений → Создать правило → Для порта → TCP → Определённые локальные порты: 25565 → Разрешить подключение → профиль вашей текущей сети (обычно Частный; при текущем Общедоступном нужен именно он) → имя SkyCraft TCP 25565. Для профиля сети: Get-NetConnectionProfile. Если Java уже разрешена и TCP проходит, нового правила не требуется.', 'Правило открывает именно входящий игровой порт. Профиль «только Частный» не сработает, если активная сеть Windows «Общедоступная». После теста ненужное созданное правило можно удалить по этому имени.'],
    ['F2','Порт слушается на хосте', 'После /skycraft host 25565 на хосте: Get-NetTCPConnection -State Listen -LocalPort 25565 | Select-Object LocalAddress,LocalPort,OwningProcess. Если пусто — сервер не открылся/закрыт или команда не выполнилась. Если порт занят до запуска хоста, выберите другой свободный внутренний порт и исправьте весь ENDPOINT/проброс/правило вместе.', 'LISTEN на нужном порту и сообщение «Мир открыт» — локальный сервер готов; внешний вход всё равно проверяет клиент. 0.0.0.0/:: в LISTEN — адрес привязки, не адрес приглашения.'],
]

TRANSPORTS = [
    ['C1','Начальная конфигурация DIRECT', 'На указанном в сценарии ПК: G2–G5. Файл MINECRAFT\\config\\skycraft.properties должен содержать по одной строке:\njoin=\nnetwork.mode=DIRECT\nnetwork.hostPort=25565\nnetwork.advertisedAddress=\nnetwork.timeoutMillis=10000\nПустые значения — сразу конец строки после =. Если ключ отсутствовал, добавьте его в конец. Сохраните Ctrl+S и заново запустите SKSE/MO2.', 'Для туннельного VPN режим SkyCraft тоже DIRECT: соединение использует маршруты Windows. Имена параметров и значение DIRECT вписываются в файл, а не вводятся в чат. В /join вручную указывается игровой адрес.'],
    ['C2','VPN в режиме туннеля', 'Для N04/N08 на клиенте: выполните C1, откройте свой VPN-клиент, выберите профиль/сервер, включите режим VPN/TUN/туннель и подключение. Запишите название программы, её версию, название сервера без ключей, время и порядок запуска. Для LAN найдите настройку Allow LAN/доступ к локальной сети; укажите её фактическое значение. Хост в этих сценариях остаётся с выключенными инструментами.', 'Названия кнопок зависят от VPN-программы; режим берите из её интерфейса, а не по наличию процесса. Если не можете определить режим, запишите unknown и PARTIAL. При пропаже TCP сравните InterfaceAlias/SourceAddress в выводе Test-NetConnection с базовым прогоном.'],
    ['C3','Найти адрес и порт прокси клиента', 'На клиенте откройте настройки используемой VPN/прокси-программы. Найдите поле SOCKS port / HTTP port / Mixed port / Local proxy: перепишите отдельно тип, адрес и порт. Если там нет адреса, смотрите документированный адрес прослушивания этой программы; не подставляйте его наугад.\nДля системного HTTP-прокси: Win+I → Сеть и Интернет → Прокси → ручная настройка, прочитайте адрес/порт. Один URL автоматического PAC-скрипта не является адресом proxy listener.\nВ PowerShell по G6 проверьте реальный порт, например для порта 7890:\nGet-NetTCPConnection -State Listen -LocalPort 7890', '7890 — пример; замените его числом из своей программы. PROXY_ENDPOINT = прокси на клиентском ПК, ENDPOINT = игровой хост. Если показан только TUN без HTTP/SOCKS listener, N05/N06 отметьте BLOCKED: сначала нужен поддерживаемый локальный прокси. Номер порта системного прокси не доказывает поддержку SOCKS5.'],
    ['C4','Записать SOCKS5 в файл', 'Только клиент: закройте обе игры по G2; откройте MINECRAFT\\config\\skycraft.properties; по G4 задайте:\njoin=\nnetwork.mode=SOCKS5\nnetwork.proxy=АДРЕС_ПРОКСИ:ПОРТ_ПРОКСИ\nЗамените последнюю строку фактическими значениями C3. Например network.proxy=127.0.0.1:7890 допустима только если ваша программа действительно предоставляет SOCKS5 на 7890.\nЕсли прокси требует имя и пароль, задайте отдельные строки network.proxy.username=ВАШЕ_ИМЯ и network.proxy.password=ВАШ_ПАРОЛЬ; если не требует — обе строки оставьте с пустым значением. Ctrl+S, запуск G5.', 'Проверьте в чате /skycraft netcheck ENDPOINT, заменив ENDPOINT игровым адресом по A2/A7/A9. /join тоже получает игровой адрес. Секреты остаются в локальном файле; не копируйте его в отчёт. Игровое DNS-имя разрешает прокси.'],
    ['C5','Записать HTTP CONNECT в файл', 'Только клиент: выполните G2–G5 для MINECRAFT\\config\\skycraft.properties. Параметры:\njoin=\nnetwork.mode=HTTP_CONNECT\nnetwork.proxy=АДРЕС_ПРОКСИ:HTTP_ПОРТ\nПодставьте реальные значения HTTP/mixed listener из C3. Имя/пароль задайте отдельными ключами как в C4, либо оставьте оба пустыми при отсутствии авторизации. Затем в чате выполните /skycraft netcheck ENDPOINT с игровым адресом.', 'В events.csv по R5 смотрите status_code на этапе HTTP: 200 — туннель принят; 403/405 — запрет/неподдерживаемый CONNECT; 407 — требуется/не принята авторизация. Если разрешён только 443, нужен разрешённый внешний игровой порт и соответствующий проброс A6; простая замена числа в /join не создаёт сервер.'],
    ['C6','Зафиксировать Cloudflare и zapret', 'В «Условия прогонов» для нужного Run ID, в столбце режимов ЭТОГО ПК, запишите название/версию Cloudflare One Client, режим DNS-only либо трафик+DNS, отображаемый DNS-протокол и название/версию zapret с выбранным профилем/имёнем запускаемого BAT. Версию ищите в «О программе» клиента; профиль zapret — в выбранном BAT/настройках запуска. Запишите порядок включения и UTC по G7. Меняйте сторону, указанную в сценарии.', 'Если интерфейс не показывает UDP, отметьте «DNS-протокол не подтверждён»: PARTIAL для условия UDP. Не приписывайте UDP по наличию warp-svc. Для N02/N03 прочие инструменты выключены; для N07–N09 их включают последовательно. Хост с инструментами проверяют H01/H02.'],
]

STEPS = [
    ['1','Зафиксировать условия', 'В рабочей копии XLSX из P7 найдите строку RUN_ID в «Условия прогонов». По R6 запишите свои версии, режимы и внутренний порт 25565. Загрузите тестовое сохранение Skyrim в согласованной локации P4; SkyCraft автоматически открывает собственный мир MINECRAFT\\saves\\SkyCraft. До изменения блоков выполните G3.', 'Заполните ту же строку XLSX своими версиями/режимами. Получите ENDPOINT по A2 для LAN, A6–A7 для внешнего IPv4 или A8–A9 для IPv6, запишите его и источник. Оставьте своё тестовое сохранение Skyrim загруженным. Настройки network.* перед прогоном изменяйте только в MINECRAFT\\config\\skycraft.properties по G2–G5.', 'RUN_ID замените названием выбранной попытки, например I01_01. Один Run ID у обоих ПК, роли host/client. Здесь ещё не нажимайте /join.'],
    ['2','Запустить лог', 'В чате Skyrim по G6, по одной команде:\n/skycraft debug start RUN_ID host\n/skycraft debug status\nRUN_ID замените ID попытки, например /skycraft debug start I01_01 host.', 'В чате Skyrim, по одной команде:\n/skycraft debug start RUN_ID client\n/skycraft debug status\nНапример /skycraft debug start I01_01 client.', 'status должен показать включённый логгер и путь JSONL с вашим ID и ролью. Запишите путь в заметки. Начало UTC после теста возьмите из первого события environment по G7/R5. При ошибке записи остановите прогон и соберите R1.'],
    ['3','Открыть мир', '/skycraft host 25565. Дождитесь сообщения «Мир открыт на порту 25565», затем /skycraft debug mark HOST_READY. Проверьте LISTEN по F2. Если внешний порт отличается от 25565, внутри оставьте свой HOST_PORT; в приглашении передайте внешний.', 'Не выполняйте /host. Дождитесь от хоста сообщения готовности с ENDPOINT, например реальный IPv4:25565. Не закрывайте своё Skyrim-сохранение.', 'Мир хоста открыт, порт слушается. Запишите внутренний и внешний порты в условиях. Хост не должен уходить из своего мира во время теста.'],
    ['4','Проверить TCP и маршрут', 'Держите мир открытым; при False у клиента проверьте F1/F2 и A4–A7. Не выполняйте /join в свой мир из этого же экземпляра.', 'Для DIRECT выполните Windows-команду из A3/A7/A9 и запишите TcpTestSucceeded, RemoteAddress, InterfaceAlias. В чате: /skycraft netcheck ENDPOINT (замените целиком, например /skycraft netcheck 192.168.1.20:25565). При SOCKS/HTTP основной результат — netcheck, Windows TCP идёт напрямую.', 'Успех TCP/netcheck не означает успешный игровой вход. При отказе зафиксируйте текст, UTC, режим, status_code/тип исключения; дальше шаги движения не выполняйте.'],
    ['5','Войти в мир хоста', 'Оставаться в мире. Наблюдать появление второго игрока. Когда увидели его: /skycraft debug mark PEER_SEEN. Запишите, виден ли именно второй игрок, а не NPC Skyrim.', 'В чате /join ENDPOINT, например /join 192.168.1.20:25565 при этом реальном LAN адресе. Дождаться загрузки мира хоста, затем /skycraft debug mark JOIN_SEEN. /join закрывает ваш собственный Minecraft-мир на время гостевого входа; своё Skyrim-сохранение остаётся локальным.', 'У клиента в events.csv world_join с result=remote и elapsed_ms; у хоста два игрока. При ошибке — шаг X1.'],
    ['6','Проверить движение в обе стороны', 'Договоритесь текстом/голосом, кто идёт первым. Сначала хост WASD проходит от выбранного ориентира к другому примерно на 10 блоков и обратно; клиент наблюдает. Расстояние можно сверить по координатам XYZ экрана Minecraft F3: один блок = изменение X или Z на 1. Если F3 через мост не открывается, используйте оговорённые ориентиры и запишите это. Затем хост наблюдает тот же проход клиента.', 'Сначала наблюдайте хоста, затем сами пройдите к тому же ориентиру и обратно. После подтверждения обоими в чате:\n/skycraft debug mark MOVE_BOTH_OK\nПри откатах или невидимом игроке вместо этого:\n/skycraft debug mark MOVE_FAIL\nВ заметках укажите, кто и что не видел, время UTC по G7.', 'В «Прогоны → Движение обоим» YES только если оба видели движение друг друга. Запишите дрожание, откаты и задержку. Пинг берётся из отчёта R5, не оценивается на глаз.'],
    ['7','Проверить блоки в обе стороны', 'Выберите свободный тестовый участок. E открывает инвентарь Minecraft; выберите обычные доски/камень и перенесите в панель быстрого доступа, Escape закрывает инвентарь. Клавиши 1–9 выбирают слот. ПКМ по поверхности ставит блок, удержание ЛКМ по поставленному блоку ломает его. Хост ставит 3 отдельных блока, клиент подтверждает каждый, затем хост ломает их и клиент подтверждает исчезновение. После этого хост наблюдает действия клиента.', 'Подтвердите установку и удаление трёх блоков хоста, затем сами по тем же клавишам поставьте и сломайте три блока. После подтверждения обоими в чате:\n/skycraft debug mark BLOCK_BOTH_OK\nЕсли операция не дошла:\n/skycraft debug mark BLOCK_FAIL\nЗапишите операцию, место и UTC.', '«Блоки обоим» YES только после всех 12 операций: 3 установки + 3 удаления на каждой стороне. Не используйте TNT и разрушение поверхностей Skyrim. Если нет материалов или управление блоками не работает, запишите пропущенную проверку и PARTIAL; не считайте это доказательством сетевого сбоя.'],
    ['8','Проверить стабильность', 'Играть число минут из сценария, не выключать хост. Двигаться/строить безопасные блоки, следить за клиентом. Записать фактическое начало/конец и число неожиданных разрывов.', 'Играть те же минуты. При каждом разрыве записать время и сообщение. Пинг берётся из клиентского summary.json PingMeanMs/PingMaxMs; клиентские sample.ping_ms пишутся раз в 5 секунд.', 'Фактическая длительность не меньше требуемой. Любой разрыв записать, даже если повторный вход сработал. Краткий запуск — PARTIAL.'],
    ['9','Leave и повторный вход', 'Оставайтесь в мире. Поставьте один обычный блок в согласованном месте и оставьте его до повторного входа клиента. Клиент должен увидеть именно этот блок после возвращения.', 'В чате, по одной команде:\n/skycraft debug mark LEAVE_BEGIN\n/leave\nДождитесь своего мира и работающего HUD, затем:\n/skycraft debug mark OWN_WORLD_OK\n/join ENDPOINT\nВ последней команде используйте тот же реальный игровой адрес, что в шаге 5. После входа подтвердите оставленный блок:\n/skycraft debug mark REJOIN_OK', '«Leave / rejoin» OK только если свой мир восстановился, затем загрузился мир хоста и сохранился оставленный блок. При неудаче FAIL с текстом ошибки и UTC.'],
    ['10','Остановить лог', 'В чате:\n/skycraft debug mark RUN_END\n/skycraft debug stop\nПодождите 2 секунды. Держите хост открытым, пока клиент тоже не завершил запись и сбор отчёта.', 'В чате:\n/skycraft debug mark RUN_END\n/skycraft debug stop\nПодождите 2 секунды. При аварийном закрытии игры сразу собирайте прежний ID без нового запуска.', 'R2 объясняет завершение. В summary.json поле TraceStopped=true соответствует событию trace_closed; DroppedTraceEvents показывает потерянные события логгера. Если завершения нет, запишите незавершённый лог.'],
    ['11','Собрать ZIP', 'Запустите «Собрать отчёт.cmd» из распакованной папки P1. Режим 2. Заполните ВСЕ поля по R3–R4: путь G1, RUN_ID, Host, LAN/Internet, игровой адрес и отдельно порт, состояния своих программ и результат. Адрес тот же, которым пользовался клиент, включая внешний порт роутера.', 'Та же программа → 2. Поля по R3–R4: путь G1, RUN_ID, Client, та же сеть и игровой адрес/порт. При прокси в поле IP по-прежнему игровой хост; прокси/режим записываются в Notes. Для IPv6 адрес без [] и без порта.', 'Сборщик выводит полный путь ZIP. Оба берут свои файлы из reports в корне комплекта по R5. Должны быть два ZIP с одинаковым ID и разными ролями.'],
    ['12','Заполнить итог', 'Откройте рабочую XLSX, найдите строку RUN_ID в «Прогоны», заполните наблюдения и имя своего ZIP по R6. В «Условия прогонов» внесите адрес/источник и условия своего ПК. Согласуйте итог с клиентом.', 'Из своего распакованного отчёта R5 возьмите summary.json: RemoteJoinElapsedMs, PingMeanMs, PingMaxMs. RemoteJoinElapsedMs может быть списком попыток: выберите нужную по events.csv world_join с result=remote и запишите какую. Внесите имя своего ZIP. null/отсутствующее значение оставьте пустым.', 'PASS — выполнены все ожидания выбранного сценария; FAIL — ожидание нарушено; BLOCKED — нет условий; PARTIAL — часть шагов не проверена. Передайте два исходных ZIP и заполненную рабочую XLSX.'],
    ['X1','Если вход не удался', 'Проверьте F2, запишите вывод LISTEN и оставался ли хост в своём мире. В чате:\n/skycraft debug mark JOIN_FAIL_HOST\n/skycraft debug stop\nПауза 2 секунды, отчёт режима 2 по R3–R5 с прежним ID и Host.', 'Запишите полный видимый текст ошибки и UTC G7. После возврата в свой мир:\n/skycraft debug mark JOIN_FAIL\n/skycraft debug stop\nПауза 2 секунды, отчёт режима 2 с прежним ID и Client. Если игра упала, собирайте сразу, не запускайте снова.', 'После отказа пропустите шаги 6–9. Для новой попытки новый номер ID. Сохраните оба отчёта даже при неуспехе.'],
]

